FUNCTION: deleteNode
SIGNATURE: struct node* deleteNode(struct node* root, int key)

SOURCE:
```c
// C program for the function called deleteNode
// Contains target function implementation and dependency signatures

#include <stdio.h>
#include <stdlib.h>

struct node {
	int key;
	struct node *left, *right;
};

// Forward declarations for dependency functions
struct node* minValueNode(struct node* node);

// Target function implementation
struct node* deleteNode(struct node* root, int key)
{

	if (root == NULL)
		return root;


	if (key < root->key)
		root->left = deleteNode(root->left, key);


	else if (key > root->key)
		root->right = deleteNode(root->right, key);


	else {
		if (root->left == NULL) {
			struct node* temp = root->right;
			free(root);
			return temp;
		}
		else if (root->right == NULL) {
			struct node* temp = root->left;
			free(root);
			return temp;
		}

		struct node* temp = minValueNode(root->right);


		root->key = temp->key;

		root->right = deleteNode(root->right, temp->key);
	}
	return root;
}

```

